let busy=!1;async function updateValues(){if(!busy){busy=!0;try{let e=await fetch("https://192.168.1.20/gpio",{cache:"no-store"}),t=await e.text();document.getElementById("gpio").innerHTML="1"==t?"<div>La vanne 1 est ouverte</div><div class='vert'></div>":"<div>La vanne 1 est fermée</div><div class='rouge'></div>";let a=await fetch("https://192.168.1.20/voltage",{cache:"no-store"}),n=await a.text();document.getElementById("voltage").innerText=n+" V"}catch(e){console.log("Erreur updateValues:",e.message)}finally{busy=!1}}}updateValues(),setInterval((()=>{updateValues()}),3e3);const btn=document.querySelector(".btn");btn.addEventListener("click",(async()=>{try{await fetch("https://192.168.1.20/togglevanne2",{cache:"no-store"})}catch(e){console.log("Erreur button:",e.message)}})),input.addEventListener("input",(async e=>{try{await fetch("https://192.168.1.20/pwm?v="+e.target.value,{cache:"no-store"})}catch(e){console.log("Erreur PWM:",e.message)}}));